head.script:
// =============================================================================
/**
 * ins 업무 모듈(상장·발행·공시)에서 추출한 업무공통(KRX 고유) 함수.
 * 종목검색 / 컴포넌트 값 get·set / 입력검증 / 기간·일자 / 메시지 / 표준코드 매핑 /
 * 문자열 Hex / 로그저장.
 * 분석·트래킹(_trk_*) 함수는 trk.xml($c.trk), 문서 인쇄(Rexpert) 함수는
 * print.xml($c.print)로 분리하였다.
 * 함수명은 camelCase 로 표준화하고, 각 JSDoc 에 AS-IS 원본명을 병기한다.
 *
 * @author Inswave Systems
 * @class ins
 * @namespace $c.ins
 */
// =============================================================================

scwin.onpageload = function () {

};

// -----------------------------------------------------------------------------
// 0. 내부 헬퍼 (private)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name __byteLength
 * @description 문자열의 바이트 길이를 구한다. (한글 2byte, 그 외 1byte)
 * (AS-IS: getStringSize, origin: stf.xml)
 * @param {String} message 대상 문자열
 * @returns {Number} 바이트 길이
 * @hidden Y
 * @exception
 * @example
 */
scwin.__byteLength = function (message) {
    let len = 0;
    for (let i = 0; i < message.length; i++) {
        (message.charCodeAt(i) > 255) ? len += 2 : len++;
    }
    return len;
};

// -----------------------------------------------------------------------------
// 1. 종목검색 (origin: stockSearch.xml)
// -----------------------------------------------------------------------------

// 종목검색 상태 변수
scwin.stSearchId = "";
scwin.stSearchNm = "";
scwin.stSearchIsurId = "";
scwin.stSearchIsurNm = "";
scwin.stSearchId_js = "";
scwin.stSearchNm_js = "";
scwin.stSearchIsurId_js = "";
scwin.stSearchIsurNm_js = "";

/**
 * @method
 * @name jongmokSearchReset
 * @description 종목검색 관련 상태 변수를 모두 초기화한다.
 * (AS-IS: JongmokSearch_Reset, origin: stockSearch.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.jongmokSearchReset();
 */
scwin.jongmokSearchReset = function () {
    scwin.stSearchId = "";
    scwin.stSearchNm = "";
    scwin.stSearchIsurId = "";
    scwin.stSearchIsurNm = "";
    scwin.stSearchId_js = "";
    scwin.stSearchNm_js = "";
    scwin.stSearchIsurId_js = "";
    scwin.stSearchIsurNm_js = "";
    scwin.stSearchKind = "";
    scwin.stSearchMarket = "";
    scwin.stSearchOpt = "";
};

/**
 * @method
 * @name jongmokSearchRtn
 * @description 종목검색 결과(코드/명)를 호출 화면으로 반환한다. (주식·선물용)
 * (AS-IS: JongmokSearch_Rtn, origin: stockSearch.xml)
 * @param {String} sval1 종목 코드
 * @param {String} sval2 종목 명
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.jongmokSearchRtn("005930", "삼성전자");
 */
scwin.jongmokSearchRtn = function (sval1, sval2) {
    if (scwin.stSearchId_js === "") {
        stSearchId.setValue(sval1);
        if (scwin.stSearchNm !== "") {
            stSearchNm.setValue(sval2);
        }
    } else {
        scwin.stSearchId_js = sval1;
        scwin.stSearchNm_js = sval2;
    }
};

/**
 * @method
 * @name jongmokSearchRtn2
 * @description 종목검색 결과(코드/명 + 발행사 정보)를 호출 화면으로 반환한다. (ELW·수익증권용)
 * (AS-IS: JongmokSearch_Rtn2, origin: stockSearch.xml)
 * @param {String} sval1 종목 코드
 * @param {String} sval2 종목 명
 * @param {String} sval3 발행사 코드
 * @param {String} sval4 발행사 명
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.jongmokSearchRtn2(code, name, isurId, isurNm);
 */
scwin.jongmokSearchRtn2 = function (sval1, sval2, sval3, sval4) {
    if (scwin.stSearchId_js === "") {
        stSearchId.setValue(sval1);
        if (scwin.stSearchNm !== "") stSearchNm.setValue(sval2);
        if (scwin.stSearchIsurId !== "") stSearchIsurId.setValue(sval3);
        if (scwin.stSearchIsurNm !== "") stSearchIsurNm.setValue(sval4);
    } else {
        scwin.stSearchId_js = sval1;
        scwin.stSearchNm_js = sval2;
        scwin.stSearchIsurId_js = sval3;
        scwin.stSearchIsurNm_js = sval4;
    }
};

// -----------------------------------------------------------------------------
// 2. 컴포넌트 값 get/set (origin: stf.xml) — KRX 컴포넌트 명명규칙(rdo/edt/cmb/txa) 기반.
// -----------------------------------------------------------------------------

/**
 * @method
 * @name getObjectValue
 * @description 컴포넌트의 type/id 명명규칙(rdo/edt/cmb/txa)으로 값을 추출한다.
 * (AS-IS: getObjectValue, origin: stf.xml)
 * @param {Object} obj 값을 읽을 컴포넌트
 * @returns {String} 컴포넌트 값(없으면 "")
 * @hidden N
 * @exception
 * @example var v = $c.ins.getObjectValue(edt_FROM_DD);
 */
scwin.getObjectValue = function (obj) {
    // type 으로 구분 가능한 것은 text/checkbox/password (HTML control 직접 사용분).
    if (obj.type === "text") {
        return $c.str.trim(obj.getValue());
    } else if (obj.type === "checkbox") {
        return (obj.checked) ? "Y" : "N";
    } else if (obj.type === "password") {
        return $c.str.trim(obj.getValue());
    } else if (obj.id.indexOf("rdo") > -1) {
        // radio = CodeValue
        return obj.getValue();
    } else if (obj.id.indexOf("edt") > -1) {
        // emedit = text
        return $c.str.trim(obj.getText());
    } else if (obj.id.indexOf("cmb") > -1) {
        // combo
        const tmp = obj.ValueOfIndex("VALUE", obj.getSelectedIndex());
        if (tmp.indexOf("null") > -1) {
            return "";
        }
        return obj.ValueOfIndex("VALUE", obj.getSelectedIndex());
    } else if (obj.id.indexOf("txa") > -1) {
        // textarea = text
        return $c.str.trim(obj.getText());
    }
    return "";
};

/**
 * @method
 * @name setObjectValue
 * @description 컴포넌트의 type/id 명명규칙(rdo/edt/cmb/txa)으로 값을 설정한다.
 * (AS-IS: setObjectValue, origin: stf.xml)
 * @param {Object} obj 값을 설정할 컴포넌트
 * @param {String} value 설정할 값
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.setObjectValue(edt_FROM_DD, "20260101");
 */
scwin.setObjectValue = function (obj, value) {
    if (obj.type === "checkbox") {
        obj.setValue(value === "Y");
    } else if (obj.id.indexOf("cmb") > -1) {
        // combo
        obj.setSelectedIndex(obj.IndexOfColumn("VALUE", value));
    } else {
        // text / password / rdo / edt / txa 공통
        obj.setValue(value);
    }
};

// -----------------------------------------------------------------------------
// 3. 입력검증 (origin: stf.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name checkEmptyValue
 * @description 컴포넌트 값이 비었는지 검사하고, 비었으면 alert 후 포커스를 준다.
 * (AS-IS: checkEmptyValue, origin: stf.xml)
 * @param {Object} obj 검사할 컴포넌트
 * @param {String} msg 항목명(메시지에 표시)
 * @returns {Boolean} 값이 있으면 true, 비었으면 false
 * @hidden N
 * @exception
 * @example if (!$c.ins.checkEmptyValue(edt_NM, "회사명")) return;
 */
scwin.checkEmptyValue = function (obj, msg) {
    if (scwin.getObjectValue(obj) === "") {
        alert("[" + msg + "]를  입력하세요.");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkMaxLength
 * @description 컴포넌트 값의 바이트 길이가 size 를 초과하면 alert 후 포커스를 준다. (한글 2byte)
 * (AS-IS: checkMaxLength, origin: stf.xml)
 * @param {Object} obj 검사할 컴포넌트
 * @param {Number} size 허용 최대 바이트
 * @param {String} lbl 항목명(메시지에 표시)
 * @returns {Boolean} 초과하지 않으면 true
 * @hidden N
 * @exception
 * @example if (!$c.ins.checkMaxLength(edt_NM, 40, "회사명")) return;
 */
scwin.checkMaxLength = function (obj, size, lbl) {
    const overLen = scwin.__byteLength(scwin.getObjectValue(obj)) - size;
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

// -----------------------------------------------------------------------------
// 4. 기간 / 일자 (origin: stf.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name setFromToDate
 * @description 기간구분(pTp)에 따라 From/To 일자 컴포넌트를 자동 설정한다. (To 가 비면 오늘 기준)
 * (AS-IS: fn_setFromToDate, origin: stf.xml)
 * @param {Number} pTp 기간구분 (1:1주일 2:1개월 3:3개월 4:6개월 5:1년 6:2년)
 * @param {Object} pObjFrom From 일자 컴포넌트
 * @param {Object} pObjTo To 일자 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.setFromToDate(2, edt_FROM_DD, edt_TO_DD);
 */
scwin.setFromToDate = function (pTp, pObjFrom, pObjTo) {
    let vFrom = "";
    let vTo = scwin.getObjectValue(pObjTo);
    if ($c.util.isEmpty(vTo)) {
        vTo = $c.date.getServerDateTime("yyyymmdd"); // 값이 없으면 오늘 기준
    }

    switch (Number(pTp)) {
        case 1: vFrom = $c.date.addDate(vTo, -7); break;   // 1주일 전
        case 2: vFrom = $c.date.addMonth(vTo, -1); break;  // 1개월 전
        case 3: vFrom = $c.date.addMonth(vTo, -3); break;  // 3개월 전
        case 4: vFrom = $c.date.addMonth(vTo, -6); break;  // 6개월 전
        case 5: vFrom = $c.date.addYear(vTo, -1); break;   // 1년 전
        case 6: vFrom = $c.date.addYear(vTo, -2); break;   // 2년 전
        default: vFrom = vTo; break;
    }
    scwin.setObjectValue(pObjFrom, vFrom);
    scwin.setObjectValue(pObjTo, vTo);
};

/**
 * @method
 * @name setFromToDate1
 * @description 기간문자열(예: "3d"/"3m"/"3y")에 따라 From/To 일자 컴포넌트를 설정한다.
 * (AS-IS: fn_setFromToDate1, origin: stf.xml)
 * @param {String} pTerm 기간문자열 (숫자 + d/m/y, 미지정 시 1년 전)
 * @param {Object} pObjFrom From 일자 컴포넌트
 * @param {Object} pObjTo To 일자 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.setFromToDate1("3m", edt_FROM_DD, edt_TO_DD);
 */
scwin.setFromToDate1 = function (pTerm, pObjFrom, pObjTo) {
    let vFrom = "";
    let vTo = scwin.getObjectValue(pObjTo);
    if ($c.util.isEmpty(vTo)) {
        vTo = $c.date.getServerDateTime("yyyymmdd"); // 값이 없으면 오늘 기준
    }
    pTerm = pTerm.toLowerCase();
    const nIdx = pTerm.search(/d|m|y/g);
    const sTerm = Number(pTerm.substring(0, nIdx));
    const sTp = pTerm.substring(nIdx, pTerm.length);
    switch (sTp) {
        case "d": vFrom = $c.date.addDate(vTo, -sTerm); break;
        case "m": vFrom = $c.date.addMonth(vTo, -sTerm); break;
        case "y": vFrom = $c.date.addYear(vTo, -sTerm); break;
        default: vFrom = $c.date.addYear(vTo, -1); break;
    }
    scwin.setObjectValue(pObjFrom, vFrom);
    scwin.setObjectValue(pObjTo, vTo);
};

/**
 * @method
 * @name compareFromToDate
 * @description From 일자가 To 일자보다 크면 alert 후 false 를 반환한다.
 * (AS-IS: compareFromToDate, origin: stf.xml)
 * @param {Object} fromDate From 일자 컴포넌트
 * @param {Object} toDate To 일자 컴포넌트
 * @param {String} fromMsg From 항목명
 * @param {String} toMsg To 항목명
 * @returns {Boolean} 정상(From<=To)이면 true
 * @hidden N
 * @exception
 * @example if (!$c.ins.compareFromToDate(edt_FROM, edt_TO, "시작일", "종료일")) return;
 */
scwin.compareFromToDate = function (fromDate, toDate, fromMsg, toMsg) {
    if (Number(scwin.getObjectValue(fromDate)) > Number(scwin.getObjectValue(toDate))) {
        alert(fromMsg + "을(를) " + toMsg + " 이전으로 선택하세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name compareFromToDate2
 * @description 검색시작일이 검색종료일보다 크면 alert·포커스 후 false 를 반환한다.
 * (AS-IS: compareFromToDate2, origin: stf.xml)
 * @param {Object} objSDate 검색시작일 컴포넌트
 * @param {Object} objEDate 검색종료일 컴포넌트
 * @returns {Boolean} 정상(시작<=종료)이면 true
 * @hidden N
 * @exception
 * @example if (!$c.ins.compareFromToDate2(edt_SDATE, edt_EDATE)) return;
 */
scwin.compareFromToDate2 = function (objSDate, objEDate) {
    if (Number(scwin.getObjectValue(objSDate)) > Number(scwin.getObjectValue(objEDate))) {
        alert("검색시작일을  검색종료일 이전으로 선택하세요.");
        objSDate.focus();
        return false;
    }
    return true;
};

// -----------------------------------------------------------------------------
// 5. 메시지 (origin: stf.xml) — KRX 공통메시지 테이블.
// -----------------------------------------------------------------------------

