/**
 * @method
 * @name getMessageParam
 * @description KRX 공통메시지 테이블에서 key 로 메시지를 찾고, "^" 를 targetMsg 로 치환해 반환한다.
 * (AS-IS: getMessageParam, origin: stf.xml)
 * @param {String} key 메시지 코드(예: "MSG-A001")
 * @param {String} targetMsg "^" 자리에 치환할 문자열
 * @returns {String} 완성된 메시지(미정의 코드면 "MessageCode: key")
 * @hidden N
 * @exception
 * @example $c.win.alert($c.ins.getMessageParam("MSG-A001", "저장"));
 */
scwin.getMessageParam = function (key, targetMsg) {
    let content;
    for (let i = 0; i < scwin.MESSAGE_KEYS.length; i++) {
        if (key === scwin.MESSAGE_KEYS[i].key) {
            content = scwin.MESSAGE_KEYS[i].content;
            break;
        }
    }
    if (content === undefined) {
        return "MessageCode: " + key;
    }
    const count = content.indexOf("^");
    if (count > -1) {
        content = content.substring(0, count) + targetMsg + content.substring(count + 1);
    }
    return content;
};

// -----------------------------------------------------------------------------
// 6. 표준코드 매핑 (origin: function.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name getStdCdToStdTpCd
 * @description 표준코드 신청구분(std_cd_appl_contn_tp_cd)을 상세 표준유형코드로 매핑한다.
 * (AS-IS: get_stdcd2stdTpCd, origin: function.xml)
 * @param {String} stdCdApplContnTpCd 표준코드 신청구분 (01~13)
 * @param {String} type2 전자단기사채(07) 구분 시 "CP" 면 CP(7), 아니면 전단채(77)
 * @returns {String} 상세 표준유형코드
 * @hidden N
 * @exception
 * @example var tp = $c.ins.getStdCdToStdTpCd("01");
 */
scwin.getStdCdToStdTpCd = function (stdCdApplContnTpCd, type2) {
    switch (stdCdApplContnTpCd) {
        case "01": return "3";   // 채권
        case "02": return "2";   // 주권
        case "03": return "4";   // 수익증권
        case "04": return "5";   // 신주인수권증권(WR)
        case "05": return "55";  // 신주인수권증서(R)
        case "06": return "8";   // 유가증권예탁증서(DR)
        case "07": return (type2 === "CP") ? "7" : "77"; // CP(7) / 전자단기사채(77)
        case "08": return "9";   // 스트립
        case "09": return "6";   // 양도성예금증서(CD)
        case "10": return "11";  // 주식워런트증권(ELW)
        case "11": return "10";  // ELS/DLS
        case "12": return "14";  // ETN
        case "13": return "15";  // 투자계약증권
        default: return "";
    }
};

// -----------------------------------------------------------------------------
// 7. 문자열 Hex 인코딩 (origin: person.xml) — 종목코드 등 파라미터 전달용.
// -----------------------------------------------------------------------------

/**
 * @method
 * @name toHex4
 * @description 문자열의 각 문자를 4자리 16진수로 인코딩한다(대문자).
 * (AS-IS: StringToHex4, origin: person.xml)
 * @param {String} originalString 원본 문자열
 * @returns {String} 4자리 Hex 연결 문자열
 * @hidden N
 * @exception
 * @example var enc = $c.ins.toHex4("AB");
 */
scwin.toHex4 = function (originalString) {
    let returnString = "";
    for (let i = 0; i < originalString.length; i++) {
        const tmp = "0000" + (parseInt(originalString.charCodeAt(i)).toString(16));
        returnString += tmp.substring(tmp.length - 4);
    }
    return returnString.toUpperCase();
};

/**
 * @method
 * @name fromHex4
 * @description 4자리 16진수 연결 문자열을 원본 문자열로 디코딩한다.
 * (AS-IS: Hex4ToStr, origin: person.xml)
 * @param {String} encodeData 4자리 Hex 연결 문자열
 * @returns {String} 디코딩된 문자열
 * @hidden N
 * @exception
 * @example var str = $c.ins.fromHex4(enc);
 */
scwin.fromHex4 = function (encodeData) {
    let newData = "";
    let iNo = 0;
    for (let i = 0; i < encodeData.length / 4; i++) {
        const str = encodeData.substr(iNo, 4);
        newData += String.fromCharCode(parseInt("0x" + str));
        iNo += 4;
    }
    return newData;
};

// -----------------------------------------------------------------------------
// 8. 로그 저장 (origin: stf.xml) — 레거시 XHR 기반. 신규 화면은 $c.sbm 사용 권장.
// -----------------------------------------------------------------------------

/**
 * @method
 * @name createXmlObj4LogSave
 * @description 로그저장 요청용 XMLHttpRequest 객체를 생성한다.
 * (AS-IS: createXMLObj4LogSave, origin: stf.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.createXmlObj4LogSave();
 */
scwin.createXmlObj4LogSave = function () {
    if (window.XMLHttpRequest) {
        scwin.xmlHttp4LogSave = new XMLHttpRequest();
    } else if (window.ActiveXObject) {
        scwin.xmlHttp4LogSave = new ActiveXObject("Microsoft.XMLHTTP");
    }
};

/**
 * @method
 * @name startLogSave
 * @description 화면 ID/처리구분으로 로그저장 요청을 비동기 전송한다.
 * (AS-IS: startLogSave, origin: stf.xml)
 * @param {String} ver1 화면 ID (SCREN_ID)
 * @param {String} ver2 화면 처리구분 코드 (SCREN_PROCES_TP_CD)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.startLogSave("ULDINS0101", "R");
 */
scwin.startLogSave = function (ver1, ver2) {
    const url = "/common/logSaveAct.jsp?SCREN_ID=" + ver1 + "&SCREN_PROCES_TP_CD=" + ver2;
    scwin.xmlHttp4LogSave.onreadystatechange = scwin.chkStats4LogSave;
    scwin.xmlHttp4LogSave.open("GET", url, true);
    scwin.xmlHttp4LogSave.send(null);
};

/**
 * @method
 * @name chkStats4LogSave
 * @description 로그저장 XHR 응답 상태를 점검하고 완료 시 결과를 처리한다. (onreadystatechange 콜백)
 * (AS-IS: chkStats4LogSave, origin: stf.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example
 */
scwin.chkStats4LogSave = function () {
    if (scwin.xmlHttp4LogSave.readyState === 4 && scwin.xmlHttp4LogSave.status === 200) {
        scwin.viewParameter4LogSave();
    }
};

/**
 * @method
 * @name viewParameter4LogSave
 * @description 로그저장 응답(result 노드) 값을 확인한다. (alert4LogSave 가 true 일 때 alert)
 * (AS-IS: viewParameter4logSave, origin: stf.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example
 */
scwin.viewParameter4LogSave = function () {
    const xmlDoc = scwin.xmlHttp4LogSave.responseXML;
    const node = xmlDoc.getElementsByTagName("result");
    if (scwin.alert4LogSave) {
        alert(node[0].childNodes[0].nodeValue);
    }
};

/**
 * @method
 * @name doLogSave
 * @description 로그저장 전체 흐름을 실행한다(객체 생성 → 전송).
 * (AS-IS: doLogSave, origin: stf.xml)
 * @param {String} ver1 화면 ID
 * @param {String} ver2 화면 처리구분 코드
 * @param {Boolean} ver3 true 면 응답을 alert 로 표시
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.ins.doLogSave("ULDINS0101", "R");
 */
scwin.doLogSave = function (ver1, ver2, ver3) {
    scwin.createXmlObj4LogSave();
    if (ver3) scwin.alert4LogSave = true;
    scwin.startLogSave(ver1, ver2);
};
